package dev.genericpayments.platform.subscriptions.application.service;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
import dev.genericpayments.platform.subscriptions.application.model.*;import dev.genericpayments.platform.subscriptions.application.model.SubscriptionProviderModels.*;
import dev.genericpayments.platform.subscriptions.application.port.in.*;import dev.genericpayments.platform.subscriptions.application.port.out.*;
import dev.genericpayments.platform.subscriptions.domain.*;import dev.genericpayments.platform.paymentaccounts.application.port.out.LockPaymentAccountPort;import dev.genericpayments.platform.paymentaccounts.domain.*;
import dev.genericpayments.platform.customers.application.model.CustomerSessionContext;import dev.genericpayments.platform.customers.domain.*;
import java.time.*;import java.util.*;import java.util.function.Supplier;import org.junit.jupiter.api.*;
class StripeSubscriptionClientAuthorityTest {
 final StripeSubscriptionConfirmationTest f=new StripeSubscriptionConfirmationTest();
 final SubscriptionOperationStore operations=mock(SubscriptionOperationStore.class);final SubscriptionStore subscriptions=mock(SubscriptionStore.class);final SubscriptionAuthorityPort authority=mock(SubscriptionAuthorityPort.class);final SubscriptionPolicyPort policies=mock(SubscriptionPolicyPort.class);final LockPaymentAccountPort accounts=mock(LockPaymentAccountPort.class);final SubscriptionActionStore actions=mock(SubscriptionActionStore.class);
 final SubscriptionTransactionPort tx=new SubscriptionTransactionPort(){public <T>T required(Supplier<T>s){return s.get();}public <T>T requiresNew(Supplier<T>s){return s.get();}public boolean active(){return false;}};
 Instant securityNow=f.now;Instant businessNow=f.now;SubscriptionClientGrant grant;SubscriptionOperation operation=f.op;boolean revoked;
 final Clock securityClock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return securityNow;}};
 final Clock businessClock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return businessNow;}};
 SubscriptionInteractionTransaction phases;
 @BeforeEach void setup(){
  var s=f.s;when(operations.find(s.siteId(),s.id(),f.id)).thenAnswer(x->Optional.of(operation));when(operations.lock(f.id)).thenAnswer(x->operation);
  when(subscriptions.find(s.siteId(),s.id())).thenReturn(Optional.of(s));when(subscriptions.lock(s.siteId(),s.id())).thenReturn(s);when(accounts.findByIdForUpdate(f.account.id())).thenReturn(Optional.of(f.account));when(policies.load(s.siteId())).thenReturn(new SubscriptionPolicy(s.siteId(),1,true,3,false,false,false,Set.of()));
  doAnswer(x->{if(revoked)throw SubscriptionRuleErrors.conflict();return null;}).when(authority).revalidate(any(),eq(true));
  var session=((SubscriptionActor.Customer)f.context.actor()).session();grant=new SubscriptionClientGrant(UUID.randomUUID(),s.siteId(),s.customerId(),f.account.id(),s.id(),f.id,"v1",new SubscriptionClientGrant.Binding(UUID.randomUUID(),f.op.providerOperationKey(),"a".repeat(64),s.providerReference(),"cus_owned","in_owned","inpay_owned","pi_owned"),SubscriptionInteractionTransaction.digest(f.action.secret()),f.now,f.now.plusSeconds(600),null,null,session.sessionId().value(),session.origin(),f.now.plusSeconds(600));
  when(actions.billing(anyString())).thenAnswer(x->Optional.of(grant));when(actions.replay(any(),anyString(),anyString(),anyString())).thenAnswer(x->grant.consumedAt()!=null);when(actions.claimBilling(any(),any(),any(),any(),any(),anyString(),any(),anyString(),anyString(),anyString(),anyString(),any())).thenReturn(SubscriptionActionStore.ClaimDisposition.NEW);
  phases=new SubscriptionInteractionTransaction(tx,operations,subscriptions,authority,policies,accounts,actions,mock(SubscriptionPortalStore.class),mock(TrialEligibilityStore.class),businessClock);org.springframework.test.util.ReflectionTestUtils.setField(phases,"securityClock",securityClock);
 }
 SubscriptionInteractionTransaction.State state(){return phases.action(f.context,f.s.id(),f.id);}
 @Test void businessClockCannotExpireOrReviveStripeGrant(){var r=state();businessNow=f.now.plusSeconds(10000);assertThat(phases.clientGrant(f.context,r,f.action.secret())).isEqualTo(grant);businessNow=f.now.minusSeconds(10000);securityNow=f.now.plusSeconds(601);assertThatThrownBy(()->phases.clientGrant(f.context,r,f.action.secret())).isInstanceOf(RuntimeException.class);}
 @Test void finalSessionRevalidationRefusesSecretAfterLogout(){var r=state();var g=phases.clientGrant(f.context,r,f.action.secret());revoked=true;assertThatThrownBy(()->phases.clientIssued(f.context,r,g,f.action.secret(),session())).isInstanceOf(RuntimeException.class);verify(actions,never()).bindSession(anyString(),any(),anyString(),any(),any());}
 @Test void secondSessionCannotReuseBoundGrant(){var original=((SubscriptionActor.Customer)f.context.actor()).session();var other=new CustomerSessionContext(new CustomerSessionId(UUID.randomUUID()),original.siteId(),original.customerId(),original.origin(),original.scopes(),original.expiresAt());var c=new SubscriptionCommandContext(new SubscriptionActor.Customer(other),f.s.siteId(),f.s.customerId(),original.origin(),"second","req");var r=phases.action(c,f.s.id(),f.id);assertThatThrownBy(()->phases.clientGrant(c,r,f.action.secret())).isInstanceOf(RuntimeException.class);}
 @Test void claimRacingCommittedReceiptReturnsReplayBeforeMutableVersionCheck(){var r=state();consume();operation=new SubscriptionOperation(f.op.id(),f.op.siteId(),f.op.customerId(),f.op.subscriptionId(),f.op.kind(),SubscriptionOperation.Status.PROCESSING,f.op.authorityScope(),f.op.keyDigest(),f.op.fingerprint(),f.op.providerOperationKey(),f.op.expectedRevision(),f.op.policyVersion(),f.op.providerReference(),null,f.op.createdAt(),f.now,1);assertThatCode(()->assertThat(phases.claim(f.command,r,f.action)).isEqualTo(SubscriptionActionStore.ClaimDisposition.REPLAY)).doesNotThrowAnyException();}
 @Test void finalReceiptUsesSecuritySessionExpiry(){var r=state();securityNow=f.now.plusSeconds(1900);when(operations.save(any(),anyLong())).thenAnswer(x->x.getArgument(0));assertThatThrownBy(()->phases.reply(f.context,r,new Reply(Outcome.ACCEPTED,f.s.providerReference(),null))).isInstanceOf(RuntimeException.class);}
 @Test void consumedCapabilityCannotReleaseAnotherClientSession(){var r=state();consume();assertThatThrownBy(()->phases.clientGrant(f.context,r,f.action.secret())).isInstanceOf(RuntimeException.class);}
 @Test void expiredConsumedGrantCannotAuthorizeBrowserAfterReceipt(){var r=state();consume();securityNow=f.now.plusSeconds(601);assertThat(phases.browserConfirmationAllowed(f.command,r)).isFalse();}
 @Test void unconsumedGrantNeverAuthorizesBrowser(){assertThat(phases.browserConfirmationAllowed(f.command,state())).isFalse();}
 @Test void currentConsumedReceiptCanAuthorizeWinningInvocation(){var r=state();consume();assertThat(phases.browserConfirmationAllowed(f.command,r)).isTrue();}
 void consume(){var g=grant;grant=new SubscriptionClientGrant(g.id(),g.site(),g.customer(),g.account(),g.subscription(),g.operation(),g.keyVersion(),g.binding(),g.tokenDigest(),g.issuedAt(),g.expiresAt(),f.now,null,g.sessionId(),g.origin(),g.clientExpiresAt());}
 SubscriptionClientSession session(){return new SubscriptionClientSession("stripe",SubscriptionClientSession.Flow.PAYMENT,"pk_test_fixture","pi_owned_secret_canary",f.action.secret(),grant.expiresAt());}
}
